import limited_client as r, numpy as np
for cam in ['corner','corner2','corner3','corner4','topview']:
 o=r.observe(cam); im=o['rgb']; d=o['depth_m']; K=o['intrinsic']; T=o['camera_to_world']
 # segment vivid blue / red pixels in image
 masks={'red':(im[:,:,0]>100)&(im[:,:,0]>im[:,:,1]*1.6)&(im[:,:,0]>im[:,:,2]*1.4), 'blue':(im[:,:,2]>100)&(im[:,:,2]>im[:,:,0]*1.4)&(im[:,:,2]>im[:,:,1]*1.4)}
 print('\n',cam)
 for name,m in masks.items():
  ys,xs=np.where(m)
  # component-ish report points with depth and world projection from median color pixels
  if len(xs):
   # depth robust median
   u,v=np.median(xs),np.median(ys); z=np.median(d[ys,xs]);
   p=np.array([(u-K[0,2])*z/K[0,0],(v-K[1,2])*z/K[1,1],z,1]); w=T@p
   print(name,len(xs),'bbox',xs.min(),xs.max(),ys.min(),ys.max(),'uvz',u,v,z,'world',w[:3])
